import sqlite3
conn = sqlite3.connect('/root/data/eventlogs.db')
cur = conn.cursor()

malicious_guids = {'{3ddc5665-e80d-5f51-2501-000000000500}', '{3ddc5665-ed04-5f51-eb02-000000000500}', '{3ddc5665-ed04-5f51-ec02-000000000500}', '{3ddc5665-ed05-5f51-ed02-000000000500}', '{3ddc5665-ed05-5f51-f002-000000000500}', '{3ddc5665-ed06-5f51-f102-000000000500}', '{3ddc5665-ed06-5f51-f202-000000000500}', '{3ddc5665-ed08-5f51-f302-000000000500}', '{3ddc5665-ed2e-5f51-fc02-000000000500}'}

# Let's extract PID from Sysmon events (message column usually has ProcessId)
# Since some GUIDs don't have event 1 in the database, we can also extract from any event that has a process_guid and message.
for guid in malicious_guids:
    cur.execute(\"SELECT message FROM events WHERE process_guid = ? AND message LIKE '%ProcessId:%' LIMIT 1;\", (guid,))
    res = cur.fetchone()
    if res:
        import re
        pid_match = re.search(r'ProcessId:\s*(\d+)', res[0])
        if pid_match:
            pid = int(pid_match.group(1))
            print(f'Guid: {guid} | Dec PID: {pid} | Hex PID: {hex(pid)}')
        else:
            print(f'Guid: {guid} | No PID found in message: {res[0][:100]}')
    else:
        # Let's try parsing process_guid to extract PID if possible, or search for other occurrences
        cur.execute(\"SELECT message FROM events WHERE process_guid = ? LIMIT 5;\", (guid,))
        rows = cur.fetchall()
        pids = set()
        for row in rows:
            import re
            pid_match = re.search(r'ProcessId:\s*(\d+)', row[0])
            if pid_match:
                pids.add(int(pid_match.group(1)))
            pid_match_2 = re.search(r'ProcessID:\s*(\d+)', row[0])
            if pid_match_2:
                pids.add(int(pid_match_2.group(1)))
        if pids:
            for pid in pids:
                print(f'Guid: {guid} | Dec PID: {pid} | Hex PID: {hex(pid)}')
        else:
            print(f'Guid: {guid} | No events with ProcessId found.')
